# Hand-written semantics for the 91 row opcodes. Keys: code -> dict
S={}
def e(code,name,cls,writes,rd,ctl='—',log='—',note=''):
    S[name]=dict(code=code,name=name,cls=cls,writes=writes,rd=rd,ctl=ctl,log=log,note=note)
seq='—'
# ---------------- integer ALU
e(0,'NOP','S 3','no (rd slot is register x0)','nothing: a padding row is never interpreted (no `execute_instruction` case; it would reach `default:` → `unreachable()`)', 'pc and `instr_idx` held (`hold`, spec 4.19.6); the record is all zeros','—','padding only')
e(1,'ADD','S 3','yes','(rs1 + rs2) mod 2⁶⁴')
e(2,'ADDI','S 3','yes (the NOP form writes x0: dropped)','(rs1 + imm) mod 2⁶⁴; imm is the slot\'s 64-bit value (sign-extended when the row was built). Load-immediate form `ADDI rd, x0, imm`: rd = imm. NOP form `ADDI x0, x0, 0`: nothing')
e(3,'SUB','S 3','yes','(rs1 − rs2) mod 2⁶⁴; with rs1 = x0 (BLAKE2): (0 − rs2) mod 2⁶⁴')
e(4,'XOR','S 3','yes','rs1 ⊕ rs2')
e(5,'XORI','S 3','yes (dropped when rd = x0, as in SC)','rs1 ⊕ imm')
e(6,'OR','S 3','yes','rs1 ∨ rs2')
e(7,'ORI','S 3','yes','rs1 ∨ imm; load-immediate form `ORI rd, x0, imm`: rd = imm')
e(8,'AND','S 3','yes','rs1 ∧ rs2')
e(9,'ANDI','S 3','yes','rs1 ∧ imm')
e(159,'ANDN','S 3','yes','rs1 ∧ ¬rs2')
e(16,'SLT','S 3','yes','1 if s64(rs1) < s64(rs2), else 0')
e(17,'SLTI','S 3','yes','1 if s64(rs1) < s64(imm), else 0')
e(18,'SLTU','S 3','yes','1 if rs1 <ᵤ rs2, else 0')
e(19,'SLTIU','S 3','yes','1 if rs1 <ᵤ imm, else 0; imm is the sign-extended immediate compared as unsigned (imm −1 is 2⁶⁴ − 1)')
e(63,'ADDW','S 3','yes','sx32((rs1 + rs2) mod 2³²): the 64-bit sum wraps, then bits [31:0] are sign-extended')
e(64,'ADDIW','S 3','yes','sx32((rs1 + imm) mod 2³²)')
e(62,'SUBW','S 3','yes','sx32((rs1 − rs2) mod 2³²)')
e(110,'VirtualSignExtendWord','S 3','yes','sx32(rs1[31:0]); the rs2 slot (immediate 0) is ignored')
e(111,'VirtualZeroExtendWord','S 3','yes','rs1 ∧ 0xFFFF_FFFF; rs2 slot ignored')
e(127,'VirtualNegateIf','S 3','yes','(0 − rs2) mod 2⁶⁴ if s64(rs1) < 0 (bit 63 of rs1 set), else rs2. −INT64_MIN wraps to INT64_MIN')
e(128,'VirtualMovsign','S 3','yes','2⁶⁴ − 1 if rs1[63] = 1, else 0; rs2 slot (immediate 0) ignored')
e(107,'VirtualRev8W','S 3','yes','bswap32(rs1[31:0]) in [31:0] and bswap32(rs1[63:32]) in [63:32]: each 32-bit half byte-reversed in place, the halves not swapped; rs2 slot (immediate 0) ignored')
# ---------------- multiply
e(43,'MUL','M 5','yes','(rs1 · rs2) mod 2⁶⁴, the low half of the 128-bit product (signedness doesn\'t matter)')
e(114,'VirtualMULI','M 5','yes','(rs1 · imm) mod 2⁶⁴; for SLLI the immediate is 2^(shamt mod 64), so this is rs1 << shamt')
e(65,'MULW','M 5','yes','sx32((rs1 · rs2) mod 2³²): only the low 32 bits of the product matter, sign-extended')
e(115,'VirtualMULIW','M 5','yes','sx32((rs1 · imm) mod 2³²); for SLLIW imm = 2^(shamt mod 32), zero-extended from 32 bits')
e(45,'MULHU','M 5','yes','⌊rs1 · rs2 / 2⁶⁴⌋, both unsigned: the high half of the unsigned 128-bit product. Maximum (2⁶⁴−1)² gives 2⁶⁴ − 2')
# ---------------- shifts / bitmasks
e(116,'VirtualPow2','S 3','yes','2^(rs1 mod 64) (shift amount masked to 6 bits); rs2 slot (immediate 0) ignored')
e(121,'VirtualPow2W','S 3','yes','zx32(2^(rs1 mod 32)): masked to 5 bits and **zero-extended** (amount 31 gives 0x0000_0000_8000_0000, not sign-extended)')
e(117,'VirtualShiftRightBitmask','S 3','yes','with s = rs1 mod 64: 2⁶⁴ − 2^s, i.e. bits [63:s] set (s = 0 gives all ones). This is the mask whose tz is s, for VirtualSRL/SRA')
e(146,'VirtualShiftRightBitmaskW','S 3','yes','with s = rs1 mod 32: 2³² − 2^s, i.e. bits [31:s] set and [63:32] clear (zero-extended)')
e(118,'VirtualSRL','S 3','yes','rs1 >> tz(rs2), logical, with rs2 a bitmask from VirtualShiftRightBitmask (never 0). tz(0) = 64 is undefined behaviour in the tracer (see F6)')
e(119,'VirtualSRLI','S 3','yes','rs1 >> tz(imm), logical; imm = 2⁶⁴ − 2^(shamt mod 64) from the expansion (never 0), so tz(imm) = shamt mod 64')
e(129,'VirtualSRA','S 3','yes','s64(rs1) >> tz(rs2), arithmetic (sign bits shifted in); rs2 a bitmask, never 0')
e(120,'VirtualSRAI','S 3','yes','s64(rs1) >> tz(imm), arithmetic; imm as for VirtualSRLI')
e(147,'VirtualSRLW','S 3','yes','sx32(rs1[31:0] >> (tz(rs2) mod 32)): a logical shift of the low word, then the 32-bit result is **sign-extended** (a shift of 0 sign-extends rs1[31:0]); rs2 from VirtualShiftRightBitmaskW')
e(148,'VirtualSRLIW','S 3','yes','sx32(rs1[31:0] >> (tz(imm) mod 32)); imm = 2³² − 2^(shamt mod 32) from the expansion')
e(149,'VirtualSRAW','S 3','yes','sx32(s32(rs1[31:0]) >> (tz(rs2) mod 32)), arithmetic on the low word')
e(150,'VirtualSRAIW','S 3','yes','sx32(s32(rs1[31:0]) >> (tz(imm) mod 32)); imm as for VirtualSRLIW')
e(131,'VirtualROTRI','S 3','yes','rotr64(rs1, tz(imm) mod 64); the rotation is encoded as the immediate\'s trailing zeros (keccak uses masks such as 0xFFFF_FFFF_FFF0_0000). tz(0) = 64 rotates by 64, the identity (`std::rotr` is defined for any count)')
e(132,'VirtualROTRIW','S 3','yes','zx32(rotr32(rs1[31:0], min(32, tz(imm)))): rs1\'s upper half is dropped, the result is **zero-extended**, and a rotation of 32 (tz ≥ 32, including imm = 0) is the identity on the low word')
e(158,'VirtualXORROTL1','S 3','yes','rs1 ⊕ rotl64(rs2, 1) (note: rs2 is rotated, not the XOR)')
for c,n,k in [(133,'VirtualXORROT63',63),(134,'VirtualXORROT32',32),(135,'VirtualXORROT24',24),(136,'VirtualXORROT16',16)]:
    e(c,n,'S 3','yes',f'rotr64(rs1 ⊕ rs2, {k})')
for c,n,k in [(137,'VirtualXORROTW16',16),(138,'VirtualXORROTW12',12),(139,'VirtualXORROTW8',8),(140,'VirtualXORROTW7',7),(143,'VirtualXORROTW22',22),(144,'VirtualXORROTW19',19),(145,'VirtualXORROTW6',6)]:
    e(c,n,'S 3','yes',f'zx32(rotr32(rs1[31:0] ⊕ rs2[31:0], {k})): upper halves dropped, result **zero-extended**')
# ---------------- sub-word memory helpers
e(154,'VirtualAlignAddr','S 3','yes','(rs1 + imm) mod 2⁶⁴ with bits [2:0] cleared')
e(152,'VirtualWindowMaskB','S 3','yes','0xFF << 8·(a mod 8), a = (rs1 + imm) mod 2⁶⁴')
e(153,'VirtualWindowMaskH','S 3','yes','0xFFFF << 8·(a ∧ 6), a = rs1 + imm (bit 0 of a ignored)')
e(141,'VirtualWindowMaskW','S 3','yes','0xFFFF_FFFF << 32·a[2], a = rs1 + imm (bits [1:0] of a ignored)')
e(155,'VirtualShiftDataB','S 3','yes','(rs1 ∧ 0xFF) << 8·(rs2 mod 8)')
e(156,'VirtualShiftDataH','S 3','yes','(rs1 ∧ 0xFFFF) << 8·(rs2 ∧ 6)')
e(157,'VirtualShiftDataW','S 3','yes','(rs1 ∧ 0xFFFF_FFFF) << 8·(rs2 ∧ 4), i.e. by 0 or 32')
e(151,'VirtualPext','S 3','yes','pext(rs1, rs2): the bits of rs1 at the 1-bits of rs2, packed into rd from bit 0 up, in ascending bit order; rs2 = 0 gives 0. With the contiguous masks it receives (always a VirtualWindowMask row): (rs1 ∧ rs2) >> tz(rs2)')
e(142,'VirtualPextSigned','S 3','yes (dropped when rd = x0, as in LR.W)','as VirtualPext, giving n = popcount(rs2) bits; then if the bit of rs1 at the highest set bit of rs2 is 1 and n < 64, bits [63:n] are set (sign extension from the window\'s top bit); rs2 = 0 gives 0')
# ---------------- control
for c,n,cond in [(28,'BEQ','rs1 = rs2'),(29,'BNE','rs1 ≠ rs2'),(30,'BLT','s64(rs1) < s64(rs2)'),(31,'BGE','s64(rs1) ≥ s64(rs2)'),(32,'BLTU','rs1 <ᵤ rs2'),(33,'BGEU','rs1 ≥ᵤ rs2')]:
    e(c,n,'S 3','no (rd slot is the immediate)','—',f'if {cond}: new pc = (pc + imm) mod 2⁶⁴, imm from the **rd** slot; else new pc = pc. Then the common rule (§1.4): a target equal to pc (imm = 0) is sequential; a target of 0 ends the program')
e(34,'JAL','S 3','yes','(pc + pc_increment) mod 2⁶⁴, the link; pc_increment is 2 or 4 (a JAL row is always its expansion\'s last)','new pc = (pc + imm) mod 2⁶⁴, imm from the **rs1** slot; **if imm = 0, new pc = 0 (program end), unconditionally in the tracer** (F1)')
e(35,'JALR','S 3','yes','(pc + pc_increment) mod 2⁶⁴, computed before rd is written, so rd = rs1 reads the old rs1','new pc = ((rs1 + imm) mod 2⁶⁴) ∧ ¬1, imm from the **rs2** slot; a target equal to pc is sequential, a target of 0 ends the program')
e(36,'AUIPC','S 3','yes','(pc + imm) mod 2⁶⁴, imm from the **rs1** slot and pc the **source instruction\'s** pc (`risc_pc`, the same for every row of an expansion, including ECALL\'s AUIPC row)')
e(37,'LUI','S 3','yes','imm, from the **rs1** slot: the already shifted and sign-extended U-immediate (e.g. 0xFFFF_FFFF_8000_0000)')
# ---------------- memory and log
e(54,'LD','L 3','yes (dropped when rd = x0, only in LR.D with rd = x0)','the log word (the 64-bit memory value at rs1 + imm; the tracer with RAM reads the aligned 8-byte word there)','—','1 read-log word')
e(53,'SD','L 3','no (rd slot is the immediate)','—','—','1 write-log word: the memory pre-value')
e(122,'VirtualAdvice','L 3','yes','the log word; rs1 and rs2 slots are immediates 0','—','1 read-log word')
# advice opcodes (tracer computes; replayer takes the log)
e(160,'VirtualAdviceDivU','L 3','yes (as VirtualAdvice)','tracer: 2⁶⁴ − 1 if rs2 = 0, else ⌊rs1 / rs2⌋ unsigned. Replayer: the log word (written as `VirtualAdvice rd, 0, 0`)','—','1 read-log word')
e(162,'VirtualAdviceDiv','L 3','yes (as VirtualAdvice)','tracer: 2⁶⁴ − 1 if rs2 = 0; INT64_MIN if rs1 = INT64_MIN and rs2 = −1; else s64(rs1) / s64(rs2) truncated toward 0. Replayer: the log word','—','1 read-log word')
e(163,'VirtualAdviceRem','L 3','yes (as VirtualAdvice)','tracer: 0 if rs2 = 0; 2⁶³ if rs1 = INT64_MIN and rs2 = −1; else \\|trunc(s64(rs1) / s64(rs2))\\|, the **magnitude of the quotient**, not the remainder (F7). Replayer: the log word','—','1 read-log word')
e(164,'VirtualAdviceDivUW','L 3','yes (as VirtualAdvice)','tracer: 0x0000_0000_FFFF_FFFF if rs2[31:0] = 0, else zx32(rs1[31:0] / rs2[31:0]) unsigned. Replayer: the log word','—','1 read-log word')
e(166,'VirtualAdviceDivW','L 3','yes (as VirtualAdvice)','tracer, on the low words: 2⁶⁴ − 1 if rs2[31:0] = 0; 0x0000_0000_8000_0000 (**zero-extended**) if INT32_MIN / −1; else sx32(trunc(s32 / s32)). Replayer: the log word','—','1 read-log word')
e(167,'VirtualAdviceRemW','L 3','yes (as VirtualAdvice)','tracer, on the low words: 0 if rs2[31:0] = 0; 0x8000_0000 zero-extended if INT32_MIN / −1; else zx32(\\|trunc(s32 / s32)\\|), the quotient\'s magnitude. Replayer: the log word','—','1 read-log word')
# ---------------- assertions
e(108,'VirtualAssertEQ','S 3','no','—; checks rs1 = rs2')
e(123,'VirtualAssertLTE','S 3','no','—; checks rs1 ≤ᵤ rs2 (unsigned)')
e(124,'VirtualAssertValidDiv0','S 3','no','—; rs1 is the divisor, rs2 the quotient: checks rs1 ≠ 0 or rs2 = 2⁶⁴ − 1')
e(125,'VirtualAssertValidUnsignedRemainder','S 3','no','—; rs1 the remainder, rs2 the divisor: checks rs2 = 0 or rs1 <ᵤ rs2')
e(130,'VirtualAssertMulUNoOverflow','S 3','no','—; checks rs1 · rs2 < 2⁶⁴ (unsigned, `__builtin_mul_overflow`)')
e(112,'VirtualAssertHalfwordAlignment','S 3','no','—; checks (rs1 + imm) mod 2 = 0, imm in the rs2 slot')
e(113,'VirtualAssertWordAlignment','S 3','no','—; checks (rs1 + imm) mod 4 = 0, imm in the rs2 slot')
# ---------------- misc
e(109,'VirtualHostIO','S 3','yes, its own value: rd ← rd (no change)','rd\'s current value (`save_rd(regs[rd])`); rs1 and the rs2 immediate are not used by the row. Its host-side effects happen outside the trace (JIT, `transcode.cpp`)')
e(52,'FENCE','S 3','no (all three slots are immediates 0)','—: does nothing')
